export const VIEWER_IDLE_MS = 5 * 60 * 1000;
export const VIEWER_MAX_LIFETIME_MS = 30 * 60 * 1000;
const TOKEN_PATTERN = /^[A-Za-z0-9_-]{32,}$/;
const SESSION_ID_PATTERN = /^[A-Za-z0-9-]{8,128}$/i;
