const SESSION_HANDLE_PATTERN = /^s_[A-Za-z0-9_-]{32}$/;
const REPORT_HANDLE_PATTERN = /^r_[A-Za-z0-9_-]{32}$/;
const CURSOR_PATTERN = /^c_[A-Za-z0-9_-]{32}$/;
const SEARCH_CURSOR_PATTERN = /^q_[A-Za-z0-9_-]{32}$/;
const SEARCHABLE_MESSAGE_ROLES = new Set(["user", "assistant"]);

function asText(value) { return typeof value === "string" ? value.trim() : ""; }
function safeDate(value) {
  const date = new Date(value);
  return Number.isFinite(date.getTime()) ? date.toISOString().replace("T", " ").replace(/\.\d{3}Z$/, " UTC") : "Unknown time";
}
function safeCount(entries) { return Array.isArray(entries) ? entries.filter((entry) => entry?.type === "message").length : 0; }
function genericError(response, status = 404) { response.writeHead(status, { "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", "Content-Type": "text/plain; charset=utf-8" }); response.end(status === 403 ? "Forbidden" : "Not found"); }
function json(response, value, status = 200) { response.writeHead(status, { "Content-Type": "application/json; charset=utf-8" }); response.end(JSON.stringify(value)); }
function opaque(prefix) { return `${prefix}${randomBytes(24).toString("base64url")}`; }
function versionOf(info) { return { size: info.size, mtimeMs: info.mtimeMs, ctimeMs: info.ctimeMs, ino: info.ino }; }
function sameVersion(left, right) { return left && right && left.size === right.size && left.mtimeMs === right.mtimeMs && left.ctimeMs === right.ctimeMs && left.ino === right.ino; }
function boundedLimit(value, fallback, maximum) { if (value === null) return fallback; if (!/^[1-9][0-9]{0,3}$/.test(value)) return undefined; const limit = Number(value); return limit <= maximum ? limit : undefined; }
