async function snapshotStillCurrent(session, snapshot) { try { return sameVersion(snapshot.version, versionOf(await stat(session.file))); } catch { return false; } }
/** Reads a fixed bounded discovery prefix only; transcript content is opened only after selection. */
export async function discoverSessions({ sessionDirectory = defaultPiSessionDirectory(), maxCandidates = VIEWER_MAX_DISCOVERY_CANDIDATES, maxDepth = VIEWER_MAX_DISCOVERY_DEPTH, maxResults = VIEWER_MAX_CATALOG_RESULTS } = {}) {
  const root = resolve(sessionDirectory); const boundedCandidates = boundedInteger(maxCandidates, VIEWER_MAX_DISCOVERY_CANDIDATES, 1, VIEWER_MAX_DISCOVERY_CANDIDATES); const boundedDepth = boundedInteger(maxDepth, VIEWER_MAX_DISCOVERY_DEPTH, 0, VIEWER_MAX_DISCOVERY_DEPTH); const boundedResults = boundedInteger(maxResults, VIEWER_MAX_CATALOG_RESULTS, 1, VIEWER_MAX_CATALOG_RESULTS);
  const walked = await walkSessionFiles(root, { maxCandidates: boundedCandidates, maxDepth: boundedDepth }); const sessions = [];
  for (const file of walked.files) { if (relative(root, file).startsWith("..")) continue; const session = await readSessionMetadata(file); if (session) sessions.push(session); }
  const ordered = sessions.sort((left, right) => String(right.timestamp).localeCompare(String(left.timestamp)) || left.file.localeCompare(right.file)); const capped = walked.capped || ordered.length > boundedResults;
  const result = ordered.slice(0, boundedResults); Object.defineProperty(result, "capped", { value: capped, enumerable: false }); return result;
}

/** Reads only regular HTML reports from the documented default report directory. */
export async function discoverReports({ reportDirectory = defaultHindsightReportDirectory({ home: homedir() }) } = {}) {
  let entries;
  try { entries = await readdir(reportDirectory, { withFileTypes: true }); } catch (error) { if (error?.code === "ENOENT") return []; throw error; }
  const reports = [];
  for (const entry of entries) {
    if (!entry.isFile() || extname(entry.name).toLowerCase() !== ".html") continue;
    const file = join(reportDirectory, entry.name);
    try {
      const info = await stat(file);
      if (!info.isFile()) continue;
      reports.push({ name: basename(entry.name), modified: safeDate(info.mtime), file });
    } catch { /* stale report: omit it */ }
  }
  return reports.sort((left, right) => right.modified.localeCompare(left.modified));
}

/** Bounded lifetime rules are pure so the launcher never becomes a background service. */
export function viewerShouldClose({ started, lastHeartbeat, now, idleMs = VIEWER_IDLE_MS, maxLifetimeMs = VIEWER_MAX_LIFETIME_MS }) {
  return now - lastHeartbeat > idleMs || now - started > maxLifetimeMs;
}

